const $=s=>document.querySelector(s), svg=$('#map');
let level=0, route=[], zoom=1, pan=[0,0], english=false;
const xs={11:180,10:255,8:330,5:520,3:640,2:760,1:880};
const positions={}; Object.entries(xs).forEach(([n,x])=>positions[n]=[x, n==='1'?255:335]);
Object.assign(positions,{9:[330,190],7:[405,190],6:[520,190],4:[640,190]});
const nodes={hall:{x:650,y:455,z:1},west:{x:100,y:420,z:-1},east:{x:950,y:420,z:-1}};
Object.entries(positions).forEach(([n,[x,y]])=>{nodes['p'+n]={x,y,z:0};nodes['t'+n]={x,y:420,z:-1}});
const edges=[];const link=(a,b)=>edges.push([a,b]);
let sorted=Object.keys(positions).sort((a,b)=>positions[a][0]-positions[b][0]);link('west','t'+sorted[0]);sorted.forEach((n,i)=>{link('t'+n,'p'+n);if(i)link('t'+sorted[i-1],'t'+n)});link('t'+sorted.at(-1),'east');link('hall','p5');
function findRoute(start,end){const q=[[start]], seen=new Set([start]);while(q.length){const path=q.shift(),last=path.at(-1);if(last===end)return path;for(const [a,b]of edges){const next=a===last?b:b===last?a:null;if(next&&!seen.has(next)){seen.add(next);q.push([...path,next])}}}return []}
const rect=(x,y,w,h,fill,stroke='#4c6245',rx=7)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${fill}" stroke="${stroke}"/>`;
const txt=(x,y,t,size=12,color='#a9bd9a',extra='')=>`<text x="${x}" y="${y}" fill="${color}" font-size="${size}" ${extra}>${t}</text>`;
function render(){let s=`<defs><pattern id="grid" width="30" height="30" patternUnits="userSpaceOnUse"><path d="M30 0H0V30" fill="none" stroke="#5e7757" stroke-opacity=".10"/></pattern></defs><rect width="1050" height="720" fill="url(#grid)"/><g transform="translate(${pan[0]} ${pan[1]}) translate(525 360) scale(${zoom}) translate(-525 -360)">`;
// Buildings provide context on all layers; geometry is schematic, not surveyed.
s+=rect(365,270,95,310,'#29372c','#3b4e35')+txt(385,390,'STARY',12)+txt(380,408,'DWORZEC',12)+txt(380,430,'nieczynny',9);
if(level===0){Object.entries(positions).forEach(([n,[x,y]])=>{const short=[4,6,7,9].includes(+n),h=short?105:320,top=short?120:255;s+=`<g class="hit" data-platform="${n}" tabindex="0" role="button" aria-label="Peron ${n}">${rect(x-22,top,44,h,route.includes('p'+n)?'#778b48':'#536648','#809465',4)}${txt(x,top+35,n,20,'#ecf1d8','text-anchor="middle"')}</g>`;s+=`<path d="M${x-31} ${top-15}v${h+30} M${x+31} ${top-15}v${h+30}" stroke="#53624b" stroke-width="2" stroke-dasharray="4 5"/>`});s+=txt(480,625,'PLAC DWORCOWY',13)+txt(690,650,'DWORZEC LETNI →',11);s+=`<path d="M100 420H950" stroke="#bdd49d" opacity=".3" stroke-dasharray="5 7"/>`+txt(745,448,'TUNEL POD PERONAMI',9);}
if(level===-1){s+=rect(80,396,890,48,'#4d6242','#8ca775',12)+txt(390,425,'PRZEJŚCIE PODZIEMNE',12,'#d5e1c3');Object.entries(positions).filter(([n])=>![4,6,9].includes(+n)).forEach(([n,[x,y]])=>{s+=rect(x-15,355,30,42,'#354c34','#829d69',4)+txt(x,380,'↕',18,'#d7f77c','text-anchor="middle"')+txt(x,345,({'8':'8 / 9','5':'5 / 6','3':'3 / 4'})[n]||n,14,'#dce9c9','text-anchor="middle"')});s+=txt(70,480,'DWORZEC ZACHODNI',12)+txt(795,480,'STRONA WSCHODNIA',12);}
if(level===1){s+=rect(470,350,350,170,'#4d6141','#93a674',12)+rect(830,290,155,290,'#35462f','#738963',12)+txt(550,410,'HALA DWORCA',21,'#e2ebd0')+txt(858,420,'AVENIDA',18)+txt(845,445,'obszar do odrysowania',9);s+=`<path d="M820 430h10" stroke="#c3d59f" stroke-width="25"/>`;s+=rect(502,468,36,32,'#2e442d')+txt(510,491,'↕',20,'#d7f77c')+txt(555,492,'POŁĄCZENIE DEMO Z PERONEM 5',9);}
if(route.length){for(let i=1;i<route.length;i++){const a=nodes[route[i-1]],b=nodes[route[i]];if(a.z===level&&b.z===level)s+=`<path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="#13251c" stroke-width="14" fill="none"/><path d="M${a.x} ${a.y}L${b.x} ${b.y}" stroke="#d7f77c" stroke-width="7" stroke-linecap="round" fill="none"/>`;if(a.z!==b.z){const p=a.z===level?a:b.z===level?b:null;if(p)s+=`<circle cx="${p.x}" cy="${p.y}" r="17" fill="#d7f77c"/>`+txt(p.x,p.y+6,'↕',20,'#192b1d','text-anchor="middle"')}}const first=nodes[route[0]],last=nodes[route.at(-1)];if(first.z===level)s+=`<circle cx="${first.x}" cy="${first.y}" r="11" fill="#9de9e5" stroke="#1e3430" stroke-width="4"/>`;if(last.z===level)s+=`<circle cx="${last.x}" cy="${last.y}" r="13" fill="#d7f77c" stroke="#14281b" stroke-width="4"/>`;}
s+='</g>';svg.innerHTML=s;$('#levelTitle').textContent=english?({'1':'Station hall','0':'Platforms','-1':'Underground passage'})[level]:({'1':'Hala dworca i Avenida','0':'Poziom peronów','-1':'Przejście podziemne'})[level];document.querySelectorAll('[data-level]').forEach(b=>b.classList.toggle('active',+b.dataset.level===level));svg.querySelectorAll('[data-platform]').forEach(el=>{const choose=()=>{$('#dest').value='p'+el.dataset.platform;calculate()};el.onclick=choose;el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose()}}});}
function calculate(){route=findRoute($('#start').value,$('#dest').value);level=nodes[route[0]].z;const n=$('#dest').value.slice(1);$('#steps').innerHTML=english?`<h3>Demo route · Platform ${n}</h3><ol><li>Start: ${$('#start').selectedOptions[0].text}</li><li>Follow the line. Switch floors at ↕.</li><li>Destination: platform ${n}.</li></ol><p>Unverified connections. Do not use for travel.</p>`:`<h3>Trasa demo · Peron ${n}</h3><ol><li>Start: ${$('#start').selectedOptions[0].text}</li><li>Śledź linię. Przy ↕ przełącz poziom.</li><li>Cel: peron ${n}.</li></ol><p>Połączenia niezweryfikowane. Nie używaj do podróży.</p>`;render()}
for(let n=1;n<=11;n++)$('#dest').add(new Option('Peron '+n,'p'+n));$('#dest').value='p8';$('#route').onclick=calculate;document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{level=+b.dataset.level;render()});
function scale(d){zoom=Math.max(.6,Math.min(3,zoom*d));render()}$('#plus').onclick=()=>scale(1.2);$('#minus').onclick=()=>scale(1/1.2);$('#reset').onclick=()=>{zoom=1;pan=[0,0];render()};svg.addEventListener('wheel',e=>{e.preventDefault();scale(e.deltaY<0?1.08:1/1.08)},{passive:false});let drag;svg.onpointerdown=e=>{if(e.target.closest('[data-platform]'))return;drag={x:e.clientX,y:e.clientY,p:[...pan]};svg.setPointerCapture(e.pointerId)};svg.onpointermove=e=>{if(!drag)return;let k=1050/svg.getBoundingClientRect().width;pan=[drag.p[0]+(e.clientX-drag.x)*k,drag.p[1]+(e.clientY-drag.y)*k];render()};svg.onpointerup=svg.onpointercancel=()=>drag=null;
let watch=null;$('#gps').onclick=()=>{if(watch!==null){navigator.geolocation.clearWatch(watch);watch=null;$('#gps').textContent=english?'◎ Check my location':'◎ Sprawdź moją lokalizację';$('#gpsStatus').textContent=english?'Location stopped.':'Odczyt lokalizacji zatrzymany.';return}if(!navigator.geolocation){$('#gpsStatus').textContent='GPS unavailable / Lokalizacja niedostępna';return}$('#gpsStatus').textContent=english?'Waiting for a location reading…':'Oczekiwanie na pomiar lokalizacji…';watch=navigator.geolocation.watchPosition(p=>{$('#gps').textContent=english?'◎ Stop location':'◎ Zatrzymaj lokalizację';$('#gpsStatus').textContent=`${p.coords.latitude.toFixed(6)}, ${p.coords.longitude.toFixed(6)} · ±${Math.round(p.coords.accuracy)} m. `+(english?'Floor unknown. Map calibration pending.':'Piętro nieznane. Mapa wymaga kalibracji.')},e=>{$('#gpsStatus').textContent=({1:english?'Location permission denied. Enable it in your browser settings.':'Brak zgody na lokalizację. Możesz ją włączyć w ustawieniach przeglądarki.',2:english?'Location unavailable.':'Nie można ustalić lokalizacji.',3:english?'Location timed out. Try outdoors.':'Przekroczono czas pomiaru. Spróbuj na zewnątrz.'})[e.code];navigator.geolocation.clearWatch(watch);watch=null},{enableHighAccuracy:true,maximumAge:3000,timeout:15000})};
$('#lang').onclick=()=>{english=!english;document.documentElement.lang=english?'en':'pl';$('#lang').textContent=english?'PL':'EN';$('h1').innerHTML=english?'Find your<br><em>way.</em>':'Znajdź swoją<br><em>drogę.</em>';$('label[for="start"]').textContent=english?'WHERE ARE YOU?':'SKĄD RUSZASZ?';$('label[for="dest"]').textContent=english?'WHERE TO?':'DOKĄD IDZIESZ?';$('#route').innerHTML=english?'Show route <span>↗</span>':'Pokaż trasę <span>↗</span>';$('.notice').textContent=english?'PROTOTYPE • Draft schematic. Demo routes — require on-site verification.':'PROTOTYP • Schemat roboczy. Trasy demonstracyjne — do weryfikacji na dworcu.';[...$('#dest').options].forEach((o,i)=>o.text=(english?'Platform ':'Peron ')+(i+1));[...$('#start').options].forEach((o,i)=>o.text=(english?['Station hall · +1','West station · −1','East end of tunnel · −1']:['Hala dworca · +1','Dworzec Zachodni · −1','Wschodni koniec tunelu · −1'])[i]);$('#gps').textContent=watch!==null?(english?'◎ Stop location':'◎ Zatrzymaj lokalizację'):(english?'◎ Check my location':'◎ Sprawdź moją lokalizację');$('.intro').innerHTML=english?'Choose your start and platform.<br>See how the levels connect.':'Wybierz miejsce startu i peron.<br>Zobacz, jak łączą się poziomy.';if(route.length)calculate();else render()};render();
